from azure.monitor.query import MetricsQueryClient, MetricAggregationType
from datetime import datetime, timedelta, timezone
from azure.identity import DefaultAzureCredential

def get_metrics_client():
    credential = DefaultAzureCredential()
    return MetricsQueryClient(credential)

def format_timespan(start_time, end_time):
    start = datetime.fromtimestamp(start_time, tz=timezone.utc)
    end = datetime.fromtimestamp(end_time, tz=timezone.utc)
    return (start, end)

class MetricQueryRequest:
    def __init__(self, resource_id, metric, start_time, end_time, granularity=60):
        self.resource_id = resource_id
        self.metric = metric
        self.start_time = start_time
        self.end_time = end_time
        self.granularity = granularity

class MetricQueryResponse:
    def __init__(self, points):
        self.points = points

    @staticmethod
    def from_result(result):
        points = [{'timestamp': point.timestamp.timestamp(), 'value': float(point.average)}
                  for metric in result.metrics for series in metric.timeseries
                  for point in series.data if point.average is not None]
        return MetricQueryResponse(points)

def normalize_response(response):
    return [point for point in response.points if point['value'] is not None]

import boto3
from botocore.exceptions import ClientError

def check_metric_annotation_safety(payload, config=None):
    config = config or {}
    comprehend = boto3.client('comprehend', region_name=config.get('region', 'us-west-2'))
    try:
        response = comprehend.detect_sentiment(Text=payload['annotation'], LanguageCode='en')
        return response
    except ClientError as e:
        return {'error': str(e)}

import boto3

def translate_dashboard_note(payload, config=None):
    config = config or {}
    translate = boto3.client('translate', region_name=config.get('region', 'us-west-2'))
    response = translate.translate_text(Text=payload['note'], SourceLanguageCode='en', TargetLanguageCode=payload['target_language'])
    return response

import boto3
from datetime import datetime, timezone

def archive_metric_snapshot(payload, config=None):
    config = config or {}
    s3 = boto3.client('s3', region_name=config.get('region', 'us-west-2'))
    now = datetime.now(timezone.utc)
    key = f"metrics/{payload['metric']}/{now.strftime('%Y-%m-%d-%H-%M-%S')}.json"
    s3.put_object(Bucket=config['bucket'], Key=key, Body=payload['snapshot'])
    return {'key': key}
